  ('celebrations', 'collaboration', 'workspace', 'Celebrations', 'A post that celebrates finished work. kind: ms (milestone accepted), kpi (measure met its target), kr (key result met), close (project closed) or win. ref names the record (ms:MS-1, kpi:K05, kr:OKR1:kr2, proj:P5, init:I3); period is the target year for a measure. status: posted, or skipped when someone chose not to celebrate it.', '[{"name":"kind","type":"text","ref":null,"enforced":false},{"name":"ref","type":"text","ref":null,"enforced":false},{"name":"period","type":"text","ref":null,"enforced":false},{"name":"title","type":"text","ref":null,"enforced":false},{"name":"message","type":"text","ref":null,"enforced":false},{"name":"value_name","type":"text","ref":null,"enforced":false},{"name":"posted_by","type":"text","ref":"people","enforced":false},{"name":"posted_on","type":"date","ref":null,"enforced":false},{"name":"status","type":"text","ref":null,"enforced":false}]'::jsonb, 4),
